'use strict';
(() => {
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const storageKey = 'smaran-health-copilot-demo-v1';
  const initialState = {
    name: 'Rohit Sharma', email: 'rohit.demo@example.com', age: '34', bloodGroup: 'O+', height: '174', weight: '72', sex: 'Male', abha: '',
    files: [], medicines: [
      {id:1,name:'Atorvastatin',strength:'10 mg',instructions:'Once daily · As prescribed',time:'Evening',status:'Due',note:'Sample medication — verify with your clinician'},
      {id:2,name:'Vitamin D3',strength:'1000 IU',instructions:'Once daily · As prescribed',time:'Morning',status:'Taken',note:'Sample medication — verify with your clinician'},
      {id:3,name:'Metformin HCl',strength:'500 mg',instructions:'As prescribed with meal',time:'Dinner',status:'Due',note:'Sample medication — verify with your clinician'}
    ],
    events: [
      {id:1,date:'2026-10-07',type:'Lab report',title:'Comprehensive metabolic panel',description:'Report uploaded for review. Confirm the extracted values against the original document.',status:'Needs review'},
      {id:2,date:'2026-10-04',type:'Consultation',title:'Primary care follow-up',description:'Prepare questions and bring current medication list to your clinician.',status:'Planned'},
      {id:3,date:'2026-09-25',type:'Prescription',title:'Medication record updated',description:'A sample medication record was added to the demo profile.',status:'Sample'}
    ],
    symptoms: [], severity: 3, duration: '1 day', notes: '', settings: {aiProcessing:true, reminders:true, weeklyDigest:false, shareResearch:false, language:'English', theme:'light'},
    checkups: [],
  };
  let state = loadState();
  const selectedDemoPatientId = localStorage.getItem('medicore-demo-patient-id');
  const demoWorkbook = window.MEDICORE_DEMO_DATA || {};
  const selectedDemoPatient = (demoWorkbook['Patient Profiles'] || []).find(p => p.Patient_ID === selectedDemoPatientId);
  if (selectedDemoPatient) {
    state.name = selectedDemoPatient.Display_Name || 'Demo patient';
    state.email = `${selectedDemoPatient.Patient_ID.toLowerCase()}@medicore.demo`;
    state.age = String(selectedDemoPatient.Age_Years ?? '');
    state.sex = selectedDemoPatient.Sex_for_demo || '';
    state.abha = '';
    state.files = (demoWorkbook.Documents || []).filter(r => r.Patient_ID === selectedDemoPatientId).map((r, i) => ({
      id: r.Document_ID || `doc-${i}`, name: r.Document_Title || r.File_Name || 'Medical document',
      kind: guessKind(r.Document_Type || r.Document_Title || r.File_Name || ''),
      date: r.Document_Date || '', summary: r.Extracted_Key_Info || '',
      status: r.Extraction_Status || r.OCR_Status || 'Needs review', source: r.File_Name || '',
      ext: String(r.File_Name || '').match(/\.([a-z0-9]{1,5})$/i)?.[1] || '',
      size: Number.isFinite(Number(r.File_Size)) ? Number(r.File_Size) : null
    }));
    state.medicines = (demoWorkbook.Medications || []).filter(r => r.Patient_ID === selectedDemoPatientId).map((r, i) => ({
      id: r.Medication_Record_ID || i, name: r.Medication_Name_As_Documented || 'Not documented',
      strength: r.Dose_Text_As_Documented || 'Not documented', instructions: [r.Route_As_Documented, r.Timing_As_Documented].filter(Boolean).join(' · ') || 'Not documented',
      time: r.Timing_As_Documented || 'As documented', status: r.Status_in_Demo || 'Needs review',
      note: r.Safety_Note || 'Synthetic demo record — verify against the source.'
    }));
    state.events = (demoWorkbook['Timeline Events'] || []).filter(r => r.Patient_ID === selectedDemoPatientId).map((r, i) => ({
      id: r.Timeline_Event_ID || i, date: r.Event_Date || '', type: r.Event_Type || 'Record',
      title: r.Event_Title || 'Health event', description: `${r.Event_Summary || ''} ${r.Change_Comparison_Status || ''}`.trim(),
      status: r.Change_Comparison_Status || 'Needs review'
    }));
  }
  let currentRoute = 'overview';
  let activeRecordFilter = 'All';
  let activeTimelineFilter = 'All';
  let activeMedicineFilter = 'All';
  let symptomResult = null;
  let modalResolve = null;
  const routeNames = {overview:'Overview dashboard',assistant:'AI health assistant',records:'Medical records & upload',checkup:'Weekly AI checkup',medicines:'Medicine reminders',timeline:'Health timeline',symptoms:'Symptom checker',consultation:'Consultation summary',profile:'Personal health profile',settings:'Settings & privacy'};
  function loadState(){try{const raw=localStorage.getItem(storageKey);if(!raw)return structuredClone(initialState);const saved=JSON.parse(raw);return {...structuredClone(initialState),...saved,settings:{...initialState.settings,...saved.settings}}}catch(_){return structuredClone(initialState)}}
  function saveState(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch(_){toast('Browser storage is unavailable; changes may not persist.','error')}}
  function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function todayISO(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function prettyDate(value){if(!value)return 'Date not provided';const d=new Date(`${value}T12:00:00`);return Number.isNaN(d.getTime())?value:d.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}
  function toast(message,type='success'){const node=document.createElement('div');node.className=`toast ${type==='error'?'error-toast':''}`;node.textContent=message;$('#toastRegion').append(node);setTimeout(()=>node.remove(),3600)}
  function badge(text){const lower=String(text).toLowerCase();const kind=lower.includes('taken')||lower.includes('complete')||lower.includes('processed')?'success':lower.includes('review')||lower.includes('due')||lower.includes('pending')?'warning':lower.includes('urgent')||lower.includes('high')?'danger':lower.includes('planned')||lower.includes('sample')?'neutral':'info';return `<span class="badge badge-${kind}">${esc(text)}</span>`}
  function heading(title,description,actions=''){return `<div class="page-heading"><div><p class="eyebrow">PERSONAL HEALTH WORKSPACE</p><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`}
  function cardHeader(title,subtitle='',action=''){return `<div class="card-header"><div><h2 class="card-title">${title}</h2>${subtitle?`<p class="card-subtitle">${subtitle}</p>`:''}</div>${action}</div>`}
  function metric(label,value,note,icon,kind=''){return `<article class="card metric-card"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-note ${kind}">${note}</div></article>`}
  function pageActions(){return `<button class="btn btn-secondary" data-action="export-demo">⇩ Export demo data</button><button class="btn btn-primary" data-route="records">＋ Add document</button>`}
  function renderOverview(){const review=state.files.filter(f=>f.status==='Needs review').length+state.events.filter(e=>e.status==='Needs review').length;return `${heading(`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(state.name.split(' ')[0])}`,`Your health information, brought together in one calm and organized space. Last opened ${prettyDate(todayISO())}.`,pageActions())}
    <section class="hero-card"><div><p class="eyebrow">YOUR HEALTH, IN CONTEXT</p><h2>A clearer picture starts with your records.</h2><p>Upload a report or prescription to organize its details, review extracted information, and prepare better questions for your healthcare professional.</p><button class="btn btn-primary" data-route="records">Upload a health document <span>→</span></button></div><div class="hero-symbol" aria-hidden="true">✚</div></section>
    <div class="grid grid-4">${metric('Health documents',state.files.length+state.events.filter(e=>e.type!=='Consultation').length,'Across your demo timeline','▤')}${metric('Medication records',state.medicines.length,'Review against current prescriptions','✚')}${metric('Items to review',review,'Check source documents before relying on data','◷','warning')}${metric('Profile completeness',`${profileCompleteness()}%`,'Add any missing personal details','◎')}</div>
    <div class="section-heading"><div><h2>Health workspace</h2><p>Continue where you left off</p></div></div>
    <div class="grid grid-2"><article class="card">${cardHeader('Recent health activity','Your latest records and actions',`<button class="btn btn-ghost btn-sm" data-route="timeline">View timeline →</button>`)}${renderRecentEvents(4)}</article><article class="card">${cardHeader('Today’s medication reminders','Demo schedule · verify with your clinician',`<button class="btn btn-ghost btn-sm" data-route="medicines">View all →</button>`)}${state.medicines.slice(0,3).map(m=>`<div class="list-row"><span class="list-icon">✚</span><div class="list-content"><strong>${esc(m.name)} ${esc(m.strength)}</strong><p>${esc(m.time)} · ${esc(m.instructions)}</p></div>${badge(m.status)}</div>`).join('')||emptyInline('No medication records yet.','Add a medication record to build your demo schedule.')}<div class="divider"></div><div class="alert-box info-box">ⓘ Medication information is user-entered demo data. This prototype does not send reminders or verify prescriptions.</div></article></div>
    <div class="section-heading"><div><h2>Quick actions</h2><p>Tools for your next step</p></div></div><div class="grid grid-3"><button class="card quick-action" data-route="assistant"><span class="metric-icon">✧</span><strong>Ask the health assistant</strong><small>Understand records in everyday language</small></button><button class="card quick-action" data-route="checkup"><span class="metric-icon">◷</span><strong>Weekly health check-in</strong><small>Reflect on habits and wellness</small></button><button class="card quick-action" data-route="consultation"><span class="metric-icon">▧</span><strong>Prepare for a visit</strong><small>Make a shareable consultation brief</small></button></div>
    <div class="alert-box warning-box" style="margin-top:17px">⚕ <span><strong>Health information notice.</strong> This is a frontend prototype using illustrative data. It does not provide a diagnosis, validate medication safety, or replace professional medical care.</span></div>`}
  function emptyInline(title,description){return `<div class="empty-state"><h3>${title}</h3><p>${description}</p></div>`}
  function renderRecentEvents(limit=5){const all=[...state.events.map(e=>({...e,kind:e.type})),...state.files.map(f=>({id:`f${f.id}`,date:f.date,title:f.name,description:f.summary||'Uploaded document awaiting review.',status:f.status,kind:f.kind||'Document'} ) )].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,limit);if(!all.length)return emptyInline('Your timeline is ready','Upload a medical document or add an event to start organizing your history.');return all.map(e=>`<div class="list-row"><span class="list-icon">${e.kind==='Prescription'?'✚':e.kind==='Lab report'?'▥':e.kind==='Consultation'?'▧':'▤'}</span><div class="list-content"><strong>${esc(e.title)}</strong><p>${esc(e.kind)} · ${prettyDate(e.date)}${e.description?` · ${esc(e.description)}`:''}</p></div>${badge(e.status||'Saved')}</div>`).join('')}
  function profileCompleteness(){const fields=['name','age','bloodGroup','height','weight','sex'];return Math.round(fields.filter(k=>String(state[k]||'').trim()).length/fields.length*100)}
  function renderRecords(){const files=state.files.filter(f=>activeRecordFilter==='All'||f.kind===activeRecordFilter);return `${heading('Medical records & upload','Bring prescriptions, laboratory reports, and discharge summaries into one organized place. Extracted fields must be reviewed against the original document.',`<button class="btn btn-secondary" data-action="export-demo">⇩ Export records</button>`)}
    <div class="layout-main-side"><div class="stack"><article class="card">${cardHeader('Upload a medical document','Accepted: PDF, JPG, PNG · Prototype limit: 10 MB per file')}<div class="upload-zone" id="uploadZone"><div class="upload-icon">⇧</div><h3>Drag and drop a file here</h3><p>or choose a file from your device. Files are processed locally in this demo; no OCR service is connected.</p><button class="btn btn-primary" type="button" id="chooseFiles">Choose files</button><input id="fileInput" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,application/pdf,image/png,image/jpeg,image/webp" multiple hidden><p style="margin-top:10px">PDF, JPG, PNG or WEBP · Maximum 10 MB each</p></div><div id="pendingFiles"></div></article>
    <article class="card">${cardHeader('Your document library','Search, filter, and review uploaded demo files',`<span class="badge badge-neutral">${state.files.length} files</span>`)}<div class="search-row"><input class="search-input" id="recordSearch" placeholder="Search documents…" aria-label="Search documents"><div class="tabs" id="recordTabs">${['All','Lab report','Prescription','Discharge summary','Other'].map(f=>`<button class="tab ${activeRecordFilter===f?'active':''}" data-record-filter="${f}">${f}</button>`).join('')}</div></div><div id="recordList">${renderFileList(files)}</div></article></div>
    <div class="stack"><article class="card">${cardHeader('How extraction works','The current prototype does not call an OCR or AI provider')}<div class="timeline"><div class="timeline-item"><div class="timeline-date">STEP 01</div><h3>Upload and validate</h3><p>File type and size are checked before adding a local record.</p></div><div class="timeline-item"><div class="timeline-date">STEP 02</div><h3>Extract text (integration pending)</h3><p>Connect OCR such as PaddleOCR or a managed OCR API to read document text.</p></div><div class="timeline-item"><div class="timeline-date">STEP 03</div><h3>Review structured fields</h3><p>Confirm medicine names, units, dates, and reference ranges against the source.</p></div><div class="timeline-item"><div class="timeline-date">STEP 04</div><h3>Summarize with evidence</h3><p>AI summaries should cite the extracted evidence and state uncertainty clearly.</p></div></div></article><div class="alert-box warning-box">⚠ <span>Do not upload real sensitive medical records into this demo unless you understand the storage and device-sharing risks. Local browser storage is not a secure medical vault.</span></div></div></div>`}
  function renderFileList(files){if(!files.length)return emptyInline('No matching documents','Upload a file to add it to your document library.');return `<div class="file-list">${files.map(f=>`<div class="file-item"><span class="file-type">${esc(fileExtension(f))}</span><div class="file-info"><strong>${esc(f.name)}</strong><small>${esc(f.kind)} · ${prettyDate(f.date)} · ${formatBytes(f.size)}</small><div class="progress"><span style="width:${f.status==='Processed'?100:45}%"></span></div><small>${esc(f.summary||'Text extraction is not connected. Review this source manually.')}</small></div>${badge(f.status)}<button class="icon-button" data-action="remove-file" data-id="${f.id}" aria-label="Remove ${esc(f.name)}">×</button></div>`).join('')}</div>`}
  function fileExtension(file){if(file.ext)return String(file.ext).toUpperCase().slice(0,4);const name=String(file.source||file.name||'');return name.match(/\.([a-z0-9]{1,5})$/i)?.[1]?.toUpperCase()||'FILE'}
  function formatBytes(bytes){if(!Number.isFinite(bytes)||bytes<0)return 'Size not recorded';if(bytes<1024)return `${bytes} B`;if(bytes<1048576)return `${(bytes/1024).toFixed(1)} KB`;return `${(bytes/1048576).toFixed(1)} MB`}
  function renderAssistant(){return `${heading('AI health assistant','Ask questions about health information, prepare for appointments, and learn what your documents say. Responses below are a safe demo, not live AI analysis.')}<div class="layout-main-side"><div class="stack"><article class="card">${cardHeader('Ask MediCore','Try one of the example prompts or write your own question')}<div class="ai-callout"><span class="ai-star">✧</span><div><strong>Hello, ${esc(state.name.split(' ')[0])}. Let’s make health information easier to understand.</strong><p>I can help organize questions and explain general terms. I cannot diagnose you, verify a prescription, or interpret your personal test results reliably without a connected, clinically evaluated service.</p></div></div><div class="suggestions" style="display:flex;gap:7px;flex-wrap:wrap;margin:15px 0"><button class="symptom-chip" data-prompt="Help me prepare questions for my next doctor visit.">Prepare for a doctor visit</button><button class="symptom-chip" data-prompt="Explain what a lab reference range means in simple language.">Explain reference ranges</button><button class="symptom-chip" data-prompt="What information should I check on a prescription?">Understand a prescription</button></div><div class="field"><label for="assistantQuestion">Your question</label><textarea id="assistantQuestion" placeholder="Ask a general health-information question…" rows="3"></textarea></div><div style="display:flex;justify-content:flex-end"><button class="btn btn-primary" data-action="ask-assistant">Generate demo response →</button></div><div id="assistantAnswer" style="margin-top:16px"></div></article><article class="card">${cardHeader('Recent conversation','This demo does not send messages to a model')}<div id="conversationList">${emptyInline('Your conversation will appear here','Ask a question above to see a clearly labeled sample response.')}</div></article></div><div class="stack"><article class="card">${cardHeader('What MediCore can help with')}<div class="list-row"><span class="list-icon">✓</span><div class="list-content"><strong>Organize health information</strong><p>Turn documents into a clear list of dates, names, and values after you verify them.</p></div></div><div class="list-row"><span class="list-icon">✓</span><div class="list-content"><strong>Prepare appointment questions</strong><p>Summarize your concerns and list questions to discuss with a clinician.</p></div></div><div class="list-row"><span class="list-icon">✓</span><div class="list-content"><strong>Explain general terminology</strong><p>Learn the meaning of common medical terms without treating the explanation as a diagnosis.</p></div></div></article><div class="alert-box danger-box">⚕ <span><strong>Urgent symptoms?</strong> Do not rely on this tool. Seek emergency medical help for severe or rapidly worsening symptoms.</span></div></div></div>`}
  function renderCheckup(){return `${heading('Weekly AI checkup','A lightweight wellness reflection to help you notice patterns and prepare for a conversation with your care team. This is not a diagnostic assessment.')}<div class="layout-main-side"><article class="card">${cardHeader('Your weekly check-in','Answer only what you are comfortable sharing')}<form id="checkupForm"><div class="field"><label for="mood">How has your overall wellbeing felt this week?</label><select id="mood" name="mood"><option>Good</option><option>Mostly okay</option><option>Up and down</option><option>Not great</option></select></div><div class="field"><label for="sleep">Average sleep per night</label><select id="sleep" name="sleep"><option>Less than 5 hours</option><option>5–6 hours</option><option selected>7–8 hours</option><option>More than 8 hours</option></select></div><div class="field"><label for="energy">Energy level</label><div class="range-row"><input type="range" id="energy" min="1" max="10" value="6"><span class="range-value" id="energyValue">6 / 10</span></div></div><div class="field"><label for="activity">Movement or activity</label><select id="activity"><option>Less than usual</option><option selected>About usual</option><option>More than usual</option></select></div><div class="field"><label for="checkupNotes">Anything you want to remember or discuss? (optional)</label><textarea id="checkupNotes" placeholder="For example: a question to ask at my next appointment"></textarea></div><button class="btn btn-primary" type="submit">Save weekly reflection →</button></form><div id="checkupResult" style="margin-top:15px"></div></article><div class="stack"><article class="card">${cardHeader('Your reflections','Saved in this browser')}<div id="checkupHistory">${renderCheckupHistory()}</div></article><div class="alert-box info-box">ⓘ If you are concerned about a new symptom or a change in your health, contact a qualified healthcare professional. A weekly check-in cannot assess medical risk.</div></div></div>`}
  function renderCheckupHistory(){if(!state.checkups.length)return emptyInline('No check-ins yet','Your saved weekly reflections will appear here.');return state.checkups.slice().reverse().map(c=>`<div class="list-row"><span class="list-icon">◷</span><div class="list-content"><strong>${prettyDate(c.date)} · ${esc(c.mood)}</strong><p>Sleep: ${esc(c.sleep)} · Energy: ${esc(c.energy)}/10 · Activity: ${esc(c.activity)}${c.notes?` · ${esc(c.notes)}`:''}</p></div></div>`).join('')}
  function renderMedicines(){const meds=state.medicines.filter(m=>activeMedicineFilter==='All'||m.status===activeMedicineFilter);return `${heading('Medicine reminders','Keep a user-managed list of medication instructions. Always follow the prescription and advice from your clinician or pharmacist.',`<button class="btn btn-primary" data-action="add-medicine">＋ Add medication</button>`)}<div class="grid grid-4">${metric('Medication records',state.medicines.length,'User-entered demo list','✚')}${metric('Marked taken',state.medicines.filter(m=>m.status==='Taken').length,'For the current demo day','✓','positive')}${metric('Due for review',state.medicines.filter(m=>m.status==='Due').length,'Check your actual schedule','◷','warning')}${metric('Reminder delivery','Off','No notifications are sent by this prototype','♧')}</div><div class="section-heading"><div><h2>Medication schedule</h2><p>Today · ${prettyDate(todayISO())}</p></div><div class="tabs">${['All','Due','Taken','Skipped'].map(f=>`<button class="tab ${activeMedicineFilter===f?'active':''}" data-medicine-filter="${f}">${f}</button>`).join('')}</div></div><div class="stack">${meds.length?meds.map(m=>`<article class="card medicine-card"><span class="medicine-symbol">✚</span><div class="medicine-copy"><strong>${esc(m.name)} ${esc(m.strength)}</strong><p>${esc(m.instructions)}</p><p>${esc(m.time)} · ${esc(m.note||'Follow the clinician-provided directions.')}</p></div>${badge(m.status)}<div class="medicine-actions">${m.status!=='Taken'?`<button class="btn btn-primary btn-sm" data-action="medicine-status" data-id="${m.id}" data-status="Taken">Mark taken</button>`:''}<button class="btn btn-secondary btn-sm" data-action="edit-medicine" data-id="${m.id}">Edit</button><button class="btn btn-ghost btn-sm" data-action="remove-medicine" data-id="${m.id}">Remove</button></div></article>`).join(''):emptyInline('No medication records match','Change the filter or add a medication record.')}<article class="card">${cardHeader('Medication safety')}<div class="alert-box warning-box">⚠ This list is not a prescription and does not check drug interactions or dosage appropriateness. Do not start, stop, skip, or change medication based on this prototype. Confirm every detail with your healthcare professional.</div></article></div>`}
  function renderTimeline(){const entries=[...state.events.map(e=>({...e,kind:e.type})),...state.files.map(f=>({id:`f${f.id}`,date:f.date,title:f.name,description:f.summary||'Uploaded document. Review original file before relying on extracted details.',status:f.status,kind:f.kind||'Document'}))].filter(e=>activeTimelineFilter==='All'||e.kind===activeTimelineFilter).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `${heading('Health timeline','A chronological view of health events and uploaded records. Demo entries are illustrative; confirm each event against its source.',`<button class="btn btn-secondary" data-action="add-event">＋ Add event</button>`)}<article class="card">${cardHeader('Longitudinal health record',`${entries.length} visible events`,`<button class="btn btn-secondary btn-sm" data-action="export-demo">⇩ Export</button>`)}<div class="search-row"><input class="search-input" id="timelineSearch" placeholder="Search title or description…" aria-label="Search timeline"><div class="tabs">${['All','Lab report','Prescription','Discharge summary','Consultation','Other'].map(f=>`<button class="tab ${activeTimelineFilter===f?'active':''}" data-timeline-filter="${f}">${f}</button>`).join('')}</div></div><div class="timeline" id="timelineItems">${renderTimelineItems(entries)}</div></article><div class="alert-box info-box" style="margin-top:16px">ⓘ This timeline combines user-added sample events and files. It does not represent an official medical record or a verified clinical history.</div>`}
  function renderTimelineItems(entries){if(!entries.length)return emptyInline('No events yet','Add an event or upload a document to start your timeline.');return entries.map(e=>`<div class="timeline-item" data-search-text="${esc(`${e.title} ${e.description} ${e.kind}`.toLowerCase())}"><div class="timeline-date">${prettyDate(e.date)} · ${esc(e.kind)}</div><h3>${esc(e.title)} &nbsp; ${badge(e.status||'Saved')}</h3><p>${esc(e.description||'No additional details.')}</p></div>`).join('')}
  function renderSymptoms(){const symptoms=['Headache','Fatigue','Cough','Fever','Nausea','Dizziness','Acid reflux','Shortness of breath','Chest pain','Abdominal pain','Rash','Sore throat'];return `${heading('Symptom checker','Record symptoms and context to prepare for a clinical conversation. This tool cannot diagnose or safely rule out emergencies.')}<div class="layout-main-side"><article class="card">${cardHeader('Symptom details','Select all that apply; your choices are saved only when you submit')}<div class="field"><label for="symptomSearch">Find a symptom</label><input id="symptomSearch" class="search-input" placeholder="Search symptom list…"></div><div class="symptom-chip-list" id="symptomChips">${symptoms.map(s=>`<button class="symptom-chip ${state.symptoms.includes(s)?'selected':''}" data-symptom="${s}">${s}</button>`).join('')}</div><div class="divider"></div><div class="field"><label>How severe does it feel?</label><div class="range-row"><input type="range" min="1" max="10" id="severity" value="${state.severity}"><span class="range-value" id="severityValue">${state.severity} / 10</span></div><small>1 = very mild · 10 = worst imaginable</small></div><div class="field"><label for="duration">How long has this been happening?</label><select id="duration"><option ${state.duration==='Just started'?'selected':''}>Just started</option><option ${state.duration==='1 day'?'selected':''}>1 day</option><option ${state.duration==='2–3 days'?'selected':''}>2–3 days</option><option ${state.duration==='4–7 days'?'selected':''}>4–7 days</option><option ${state.duration==='More than a week'?'selected':''}>More than a week</option><option ${state.duration==='Recurring'?'selected':''}>Recurring</option></select></div><div class="field"><label for="symptomNotes">Additional context (optional)</label><textarea id="symptomNotes" placeholder="When it happens, what changes it, and any relevant context…">${esc(state.notes)}</textarea></div><button class="btn btn-primary" data-action="review-symptoms">Create visit-prep summary →</button><div id="symptomResult" style="margin-top:16px"></div></article><div class="stack"><article class="card">${cardHeader('Safety comes first')}<div class="alert-box danger-box">⚕ If you have severe chest pain, severe difficulty breathing, signs of stroke, loss of consciousness, or another life-threatening emergency, seek emergency medical help now. Do not wait for an online assessment.</div><div class="divider"></div><p class="card-subtitle">Symptoms can have many causes. A list of symptoms and a severity slider are not enough to determine a diagnosis or level of risk.</p></article><article class="card">${cardHeader('Useful details to tell a clinician')}<div class="list-row"><span class="list-icon">◷</span><div class="list-content"><strong>When it began</strong><p>Record onset, duration, and whether it is getting better or worse.</p></div></div><div class="list-row"><span class="list-icon">▤</span><div class="list-content"><strong>Relevant context</strong><p>Share current medications, allergies, medical history, and recent changes.</p></div></div><div class="list-row"><span class="list-icon">♡</span><div class="list-content"><strong>Impact on daily life</strong><p>Explain what you cannot do as usual and what concerns you most.</p></div></div></article></div></div>`}
  function renderConsultation(){return `${heading('Consultation summary','Create an editable visit-preparation brief using your own notes. Review it for accuracy before sharing with a healthcare professional.',`<button class="btn btn-secondary" data-action="print-brief">⎙ Print / save PDF</button><button class="btn btn-primary" data-action="download-brief">⇩ Download text</button>`)}<article class="print-sheet" id="printableArea"><div style="display:flex;justify-content:space-between;gap:15px;align-items:flex-start"><div><p class="eyebrow">PATIENT VISIT PREPARATION</p><h2>Clinical conversation brief</h2><p style="font-size:10px;color:var(--muted)">Prepared ${prettyDate(todayISO())} · Patient-provided notes · Not a clinician-authored medical record</p></div><span class="badge badge-info">Draft</span></div><div class="field-grid" style="margin-top:22px"><div class="field"><label for="briefPatient">Patient name</label><input id="briefPatient" value="${esc(state.name)}"></div><div class="field"><label for="briefDate">Appointment date</label><input id="briefDate" type="date" value="${todayISO()}"></div></div><div class="print-section"><h3>1. Main concerns and visit objectives</h3><div class="field"><textarea id="briefConcerns" placeholder="What would you like to discuss at your appointment?">${esc(state.notes)}</textarea></div></div><div class="print-section"><h3>2. Recent records to review</h3><ul>${state.files.length?state.files.map(f=>`<li>${esc(f.name)} — uploaded ${prettyDate(f.date)}; confirm values in original report.</li>`).join(''):'<li>No documents added yet. Attach relevant reports or bring the original records.</li>'}</ul></div><div class="print-section"><h3>3. Medication list to verify</h3><ul>${state.medicines.length?state.medicines.map(m=>`<li>${esc(m.name)} ${esc(m.strength)} — ${esc(m.instructions)} (user-entered; verify against prescription).</li>`).join(''):'<li>No medication records added.</li>'}</ul></div><div class="print-section"><h3>4. Questions for the healthcare professional</h3><div class="field"><textarea id="briefQuestions" placeholder="1. What should I understand about these results?&#10;2. Do any medicines or follow-up tests need review?&#10;3. When should I seek further care?"></textarea></div></div><div class="alert-box info-box">ⓘ This is a patient-preparation aid, not a diagnosis, prescription, or official clinical summary. Review and correct all details before sharing.</div></article>`}
  function renderProfile(){return `${heading('Personal health profile','Manage basic information and context you may want to bring to a healthcare appointment.',`<button class="btn btn-primary" data-action="save-profile">Save profile</button>`)}<div class="layout-main-side"><div class="stack"><article class="card">${cardHeader('Basic demographics & vitals','Only enter information you choose to keep in this browser')}<div class="profile-summary"><div class="profile-avatar">${esc(initials(state.name))}</div><div><h2>${esc(state.name)}</h2><p>Personal health profile · ${state.age?`${esc(state.age)} years old`:'Age not provided'}</p><span class="badge badge-neutral">User-entered details</span></div></div><div class="divider"></div><form id="profileForm"><div class="field-grid"><div class="field"><label for="profileName">Full name</label><input id="profileName" value="${esc(state.name)}" required maxlength="100"></div><div class="field"><label for="profileEmail">Email (optional)</label><input id="profileEmail" type="email" value="${esc(state.email)}"></div><div class="field"><label for="profileAge">Age</label><input id="profileAge" type="number" min="0" max="120" value="${esc(state.age)}"></div><div class="field"><label for="profileSex">Sex (optional)</label><select id="profileSex"><option ${state.sex==='Not specified'?'selected':''}>Not specified</option><option ${state.sex==='Female'?'selected':''}>Female</option><option ${state.sex==='Male'?'selected':''}>Male</option><option ${state.sex==='Intersex'?'selected':''}>Intersex</option><option ${state.sex==='Prefer not to say'?'selected':''}>Prefer not to say</option></select></div><div class="field"><label for="profileBlood">Blood group (optional)</label><select id="profileBlood"><option value="">Not provided</option>${['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(v=>`<option ${state.bloodGroup===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="profileHeight">Height (cm)</label><input id="profileHeight" type="number" min="30" max="260" value="${esc(state.height)}"></div><div class="field"><label for="profileWeight">Weight (kg)</label><input id="profileWeight" type="number" min="1" max="500" step="0.1" value="${esc(state.weight)}"></div><div class="field"><label for="profileAbha">Mock ABHA reference (optional)</label><input id="profileAbha" value="${esc(state.abha)}" maxlength="40" placeholder="DEMO-ABHA-0001"><small>Use mock data only. This is not an ABHA connection or verified identifier.</small></div></div><button class="btn btn-primary" type="submit">Save profile changes</button></form></article><article class="card">${cardHeader('Conditions, allergies & care notes','Add only verified information; avoid guessing')}<div class="field"><label for="profileConditions">Conditions to discuss (optional)</label><textarea id="profileConditions" placeholder="Enter clinician-confirmed conditions or questions…">${esc(state.conditions||'')}</textarea></div><div class="field"><label for="profileAllergies">Known allergies / adverse reactions (optional)</label><textarea id="profileAllergies" placeholder="Enter confirmed allergies, reaction, and source…">${esc(state.allergies||'')}</textarea></div><button class="btn btn-secondary" data-action="save-profile-notes">Save health notes</button></article></div><div class="stack"><article class="card">${cardHeader('Profile completeness')}<div class="metric-value">${profileCompleteness()}%</div><div class="progress"><span style="width:${profileCompleteness()}%"></span></div><p class="card-subtitle" style="margin-top:10px">Completeness only measures filled demo fields, not the quality or clinical validity of your information.</p></article><article class="card">${cardHeader('Data lineage')}<div class="list-row"><span class="list-icon">◎</span><div class="list-content"><strong>User-entered</strong><p>Information entered in this form is not clinician-verified.</p></div></div><div class="list-row"><span class="list-icon">▤</span><div class="list-content"><strong>Document-derived</strong><p>Future OCR data should link back to the source file and extraction confidence.</p></div></div><div class="list-row"><span class="list-icon">✧</span><div class="list-content"><strong>AI-generated</strong><p>Future summaries should be labeled as generated and reviewed before use.</p></div></div></article><div class="alert-box warning-box">⚠ Do not enter real ABHA numbers, passwords, or highly sensitive data in this prototype.</div></div></div>`}
  function initials(name){return String(name||'').trim().split(/\s+/).slice(0,2).map(p=>p[0]||'').join('').toUpperCase()||'U'}
  function renderSettings(){return `${heading('Settings & privacy','Choose demo preferences and manage locally stored sample data. These controls are not a production consent or security system.')}<div class="layout-main-side"><div class="stack"><article class="card">${cardHeader('Medical data & AI processing consent','Preferences for this frontend demo')}<div class="setting-row"><div><strong>Allow AI processing (demo preference)</strong><p>Records are not sent to an AI model in this build. This preference is saved locally for future integration.</p></div>${switchControl('aiProcessing',state.settings.aiProcessing)}</div><div class="setting-row"><div><strong>Medication reminder preference</strong><p>No push notifications, emails, or background reminders are sent by the current prototype.</p></div>${switchControl('reminders',state.settings.reminders)}</div><div class="setting-row"><div><strong>Weekly wellness digest</strong><p>Toggle a future feature preference. No digest is generated or sent.</p></div>${switchControl('weeklyDigest',state.settings.weeklyDigest)}</div><div class="setting-row"><div><strong>Share de-identified data for research</strong><p>This demo does not share your data. A real system would need explicit, revocable consent and governance.</p></div>${switchControl('shareResearch',state.settings.shareResearch)}</div><div class="field" style="margin-top:17px"><label for="settingsLanguage">Preferred language</label><select id="settingsLanguage"><option ${state.settings.language==='English'?'selected':''}>English</option><option ${state.settings.language==='Hindi'?'selected':''}>Hindi</option></select><small>UI language selection is a saved preference only; automatic translation is not implemented yet.</small></div><button class="btn btn-primary" data-action="save-settings">Save preferences</button></article><article class="card">${cardHeader('Connected health services & devices','No external services are connected')}<div class="list-row"><span class="list-icon">⌁</span><div class="list-content"><strong>ABDM / ABHA</strong><p>FHIR-inspired readiness is a planned integration. No ABHA login, health information exchange, or consent manager is connected.</p></div>${badge('Not connected')}</div><div class="list-row"><span class="list-icon">♡</span><div class="list-content"><strong>Wearables and health apps</strong><p>No Apple Health, Google Health Connect, or device data is imported.</p></div>${badge('Not connected')}</div></article></div><div class="stack"><article class="card">${cardHeader('Data sovereignty & account actions')}<div class="list-row"><span class="list-icon">⇩</span><div class="list-content"><strong>Export demo data</strong><p>Download the current profile, uploaded-file metadata, medicines, and timeline as JSON.</p></div><button class="btn btn-secondary btn-sm" data-action="export-demo">Export</button></div><div class="list-row"><span class="list-icon">▤</span><div class="list-content"><strong>Delete all local demo data</strong><p>Clear this app's saved data from this browser and reset the sample workspace.</p></div><button class="btn btn-danger btn-sm" data-action="reset-demo">Reset</button></div></article><div class="alert-box warning-box">🔒 This is not a certified medical data vault. Browser local storage is not encrypted by this app and may be accessible to other people using this browser profile. Do not use real patient data.</div><article class="card">${cardHeader('Security checklist')}<div class="list-row"><span class="list-icon">✓</span><div class="list-content"><strong>Client-side input escaping</strong><p>User-entered text is escaped before being rendered in HTML.</p></div></div><div class="list-row"><span class="list-icon">◷</span><div class="list-content"><strong>Production security pending</strong><p>Authentication, server-side authorization, encrypted storage, audit logs, retention controls, and clinical validation are not implemented.</p></div></div></article></div></div>`}
  function switchControl(key,checked){return `<label class="switch"><input type="checkbox" data-setting="${key}" ${checked?'checked':''} aria-label="${key}"><span class="switch-track"></span></label>`}
  function renderPage(){const renderers={overview:renderOverview,assistant:renderAssistant,records:renderRecords,checkup:renderCheckup,medicines:renderMedicines,timeline:renderTimeline,symptoms:renderSymptoms,consultation:renderConsultation,profile:renderProfile,settings:renderSettings};$('#pageContent').innerHTML=(renderers[currentRoute]||renderOverview)();$('#pageCrumb').textContent=routeNames[currentRoute]||routeNames.overview;$('#sidebarName').textContent=state.name;$('#topbarName').textContent=state.name;$$('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===currentRoute));$('#sidebar').classList.remove('open');$('#sidebarBackdrop').classList.remove('show');$('#pageContent').focus({preventScroll:true});applyLanguage();}
  function navigate(route){if(!routeNames[route])return;currentRoute=route;location.hash=route;renderPage();window.scrollTo({top:0,behavior:'smooth'})}
  function handleFiles(files){const allowed=['application/pdf','image/jpeg','image/png','image/webp'];const max=10*1024*1024;const valid=[];for(const file of files){if(!allowed.includes(file.type)){toast(`${file.name}: unsupported file type.`,'error');continue}if(file.size>max){toast(`${file.name}: file exceeds the 10 MB limit.`,'error');continue}valid.push(file)}if(!valid.length)return;valid.forEach(file=>{const id=Date.now()+Math.floor(Math.random()*10000);const ext=(file.name.split('.').pop()||'file').toLowerCase();const kind=guessKind(file.name);state.files.push({id,name:file.name,size:file.size,ext,kind,date:todayISO(),status:'Needs review',summary:'File metadata saved. OCR and AI extraction are not connected.',mime:file.type});state.events.push({id:`upload-${id}`,date:todayISO(),type:kind,title:`Uploaded ${file.name}`,description:'Review the original file; automated text extraction is not connected.',status:'Needs review'});});saveState();renderPage();toast(`${valid.length} file${valid.length===1?'':'s'} added to the local demo library.`)}
  function guessKind(name){const n=name.toLowerCase();if(/prescription|medicine|medication|rx/.test(n))return 'Prescription';if(/lab|blood|test|diagnostic|report/.test(n))return 'Lab report';if(/discharge|summary/.test(n))return 'Discharge summary';return 'Other'}
  function showModal(title,html,onSubmit){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;modalResolve=onSubmit;const dlg=$('#modal');if(typeof dlg.showModal==='function')dlg.showModal();else dlg.setAttribute('open','');}
  function closeModal(){const dlg=$('#modal');if(typeof dlg.close==='function'&&dlg.open)dlg.close();else dlg.removeAttribute('open');modalResolve=null}
  function confirmModal(title,message,submitLabel='Confirm',danger=false){return new Promise(resolve=>showModal(title,`<p style="font-size:12px;line-height:1.7;color:var(--muted)">${message}</p><div class="modal-actions"><button class="btn btn-secondary" type="button" data-modal-cancel>Cancel</button><button class="btn ${danger?'btn-danger':'btn-primary'}" type="button" data-modal-confirm>${submitLabel}</button></div>`,resolve))}
  function addMedicineModal(existing=null){const m=existing||{name:'',strength:'',instructions:'',time:'Morning',note:''};showModal(existing?'Edit medication':'Add medication',`<form id="medicineForm"><div class="field-grid"><div class="field"><label for="medName">Medicine name *</label><input id="medName" required maxlength="100" value="${esc(m.name)}"></div><div class="field"><label for="medStrength">Strength / form</label><input id="medStrength" maxlength="60" value="${esc(m.strength)}" placeholder="e.g. 10 mg"></div><div class="field full"><label for="medInstructions">Instructions (as prescribed)</label><input id="medInstructions" maxlength="160" value="${esc(m.instructions)}" placeholder="Enter exactly as prescribed"></div><div class="field"><label for="medTime">Reminder time label</label><select id="medTime">${['Morning','Afternoon','Evening','Dinner','Bedtime','Other'].map(v=>`<option ${m.time===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="medNote">Note</label><input id="medNote" maxlength="160" value="${esc(m.note||'')}"></div></div><p class="help-text">This saves a user-entered record only. It does not validate a medicine or create an actual notification.</p><div class="modal-actions"><button class="btn btn-secondary" type="button" data-modal-cancel>Cancel</button><button class="btn btn-primary" type="submit">Save medication</button></div></form>`,()=>{const name=$('#medName').value.trim();if(!name){toast('Enter a medication name.','error');return false}const record={id:existing?existing.id:Date.now(),name,strength:$('#medStrength').value.trim(),instructions:$('#medInstructions').value.trim()||'Instructions not entered',time:$('#medTime').value,note:$('#medNote').value.trim(),status:existing?.status||'Due'};if(existing)state.medicines=state.medicines.map(x=>x.id===existing.id?record:x);else state.medicines.push(record);saveState();closeModal();renderPage();toast(existing?'Medication record updated.':'Medication record added.');return true})}
  function downloadBlob(filename,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
  function exportData(){const data={exportedAt:new Date().toISOString(),notice:'Prototype data only; not a verified medical record.',profile:{name:state.name,email:state.email,age:state.age,sex:state.sex,bloodGroup:state.bloodGroup,height:state.height,weight:state.weight,abha:state.abha,conditions:state.conditions||'',allergies:state.allergies||''},files:state.files.map(({mime,...f})=>f),medicines:state.medicines,events:state.events,checkups:state.checkups,settings:state.settings};downloadBlob('medicore-demo-health-data.json',JSON.stringify(data,null,2),'application/json;charset=utf-8');toast('Demo data export prepared.')}
  function saveProfile(){const name=$('#profileName')?.value.trim();if(!name){toast('Name is required.','error');return}const age=$('#profileAge')?.value;if(age&&(+age<0||+age>120)){toast('Enter a valid age.','error');return}state.name=name;state.email=$('#profileEmail').value.trim();state.age=age;state.sex=$('#profileSex').value;state.bloodGroup=$('#profileBlood').value;state.height=$('#profileHeight').value;state.weight=$('#profileWeight').value;state.abha=$('#profileAbha').value.trim();state.conditions=$('#profileConditions')?.value||state.conditions||'';state.allergies=$('#profileAllergies')?.value||state.allergies||'';saveState();renderPage();toast('Profile saved in this browser.')}
  function askAssistant(){const q=$('#assistantQuestion')?.value.trim();if(!q){toast('Enter a question first.','error');return}const answer=`This prototype has not connected to a medical AI service, so it cannot analyze your personal records. For your question — “${q}” — a safe next step is to write down what you want clarified, check any relevant information against the original document, and discuss personal medical decisions with a qualified healthcare professional. If symptoms are severe or rapidly worsening, seek urgent medical care.`;$('#assistantAnswer').innerHTML=`<div class="ai-callout"><span class="ai-star">✧</span><div><strong>Sample response · Not generated by an AI model</strong><p>${esc(answer)}</p></div></div>`;const list=$('#conversationList');list.innerHTML=`<div class="list-row"><span class="list-icon">✧</span><div class="list-content"><strong>${esc(q)}</strong><p>${esc(answer)}</p></div></div>`;toast('Sample response shown. No AI API was called.')}
  function makeSymptomSummary(){if(!state.symptoms.length){toast('Select at least one symptom to prepare a summary.','error');return}state.severity=Number($('#severity').value);state.duration=$('#duration').value;state.notes=$('#symptomNotes').value.trim();saveState();symptomResult={symptoms:[...state.symptoms],severity:state.severity,duration:state.duration,notes:state.notes};$('#symptomResult').innerHTML=`<div class="card" style="background:var(--surface-2);box-shadow:none"><p class="eyebrow">VISIT-PREP SUMMARY · NOT TRIAGE</p><h3 style="font-size:13px;margin:0 0 9px">Your notes</h3><p style="font-size:11px;line-height:1.7">Symptoms selected: <strong>${esc(state.symptoms.join(', '))}</strong><br>Self-rated severity: <strong>${state.severity}/10</strong><br>Duration: <strong>${esc(state.duration)}</strong>${state.notes?`<br>Context: ${esc(state.notes)}`:''}</p><div class="alert-box warning-box">This summary does not estimate medical risk or provide a diagnosis. Discuss these details with a clinician. Seek emergency help for severe or life-threatening symptoms.</div><button class="btn btn-secondary" style="margin-top:12px" data-action="send-symptoms-to-brief">Add notes to consultation brief</button></div>`;toast('Visit-preparation summary created.')}
  function addHelpMessage(text, who='assistant'){
    const list=$('#helpMessages'); if(!list)return;
    const node=document.createElement('div'); node.className=`help-message ${who==='user'?'user-message':'assistant-message'}`;
    node.textContent=text; list.append(node); list.scrollTop=list.scrollHeight;
  }
  function helperReply(question){
    const q=question.toLowerCase();
    if(/upload|document|report|prescription|file/.test(q)) return 'To add a document, open “Medical records & upload” from the left menu, choose “Choose files”, and select a PDF or image under 10 MB. This demo stores file details only; it does not read the document yet.';
    if(/timeline|history|date|past/.test(q)) return 'Choose “Health timeline” in the left menu to see health events by date. You can search the list, filter by type, or add an event. Check every entry against the original record.';
    if(/doctor|appointment|visit|question/.test(q)) return 'Open “Consultation summary” to prepare notes for your visit. Write down your main concern, bring relevant reports and your current medicine list, and ask your clinician what needs follow-up.';
    if(/medicine|medication|dose|tablet|pill/.test(q)) return 'Open “Medicine reminders” to view your demo list. Always follow the current prescription and confirm unclear instructions with your doctor or pharmacist. This demo does not check doses or drug interactions.';
    if(/word|meaning|simple|explain|reference range|abnormal|result|lab/.test(q)) return 'I can explain general health terms in plain language, but this demo does not analyze your personal report. Check the value, unit, and reference range printed on the original report, and ask a healthcare professional how it applies to you.';
    if(/profile|name|age|allerg|blood/.test(q)) return 'Open “Personal health profile” to review or update details. Only enter information you are comfortable keeping in this browser; this prototype is not a secure medical vault.';
    if(/dark|theme|read|text|accessibility|large/.test(q)) return 'You can switch light/dark mode using the moon button in the top bar. Use “Aa Make text easier to read” here to enlarge and space out text across the site.';
    if(/emergency|chest pain|breath|stroke|faint|urgent/.test(q)) return 'If you may be having a medical emergency, have severe trouble breathing, chest pain, signs of stroke, fainting, or rapidly worsening symptoms, seek emergency medical help now. Do not wait for this website.';
    return 'I can help you find website features and explain general terms, but this is a demo assistant, not a live AI or medical professional. Try a shortcut above, or choose a section from the left menu. For personal medical decisions, contact a qualified healthcare professional.';
  }
  function submitHelpQuestion(question){
    const q=String(question||'').trim(); if(!q){$('#helpInput')?.focus();return;}
    addHelpMessage(q,'user'); addHelpMessage(helperReply(q),'assistant');
    const input=$('#helpInput'); if(input)input.value='';
  }
  function setHelpOpen(open){const panel=$('#helpPanel'),button=$('#helpLauncher');if(!panel||!button)return;panel.hidden=!open;button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close MediCore AI health assistant':'Open MediCore AI health assistant');if(open)$('#helpInput')?.focus();else button.focus();}
  const languageKey='smaran-ui-language-v1';
  const hiMap={
    'Overview dashboard':'डैशबोर्ड','AI health assistant':'AI स्वास्थ्य सहायक','Medical records & upload':'मेडिकल रिकॉर्ड और अपलोड','Weekly AI checkup':'साप्ताहिक स्वास्थ्य जाँच','Medicine reminders':'दवा रिमाइंडर','Health timeline':'स्वास्थ्य टाइमलाइन','Symptom checker':'लक्षण जाँच','Consultation summary':'डॉक्टर से मिलने की तैयारी','Personal health profile':'व्यक्तिगत स्वास्थ्य प्रोफ़ाइल','Settings & privacy':'सेटिंग्स और गोपनीयता',
    'WORKSPACE':'कार्य क्षेत्र','YOUR SPACE':'आपकी जगह','Privacy-first prototype':'गोपनीयता-केंद्रित प्रोटोटाइप','Demo data stays in this browser':'डेमो डेटा इसी ब्राउज़र में रहता है','Workspace':'कार्य क्षेत्र','DEMO MODE':'डेमो मोड','Ask MediCore':'MediCore से पूछें','Simple help for your health workspace':'आपके स्वास्थ्य कार्यक्षेत्र के लिए आसान मदद','Hi! What would you like help with?':'नमस्ते! आपको किस चीज़ में मदद चाहिए?','Choose a shortcut or type a question in your own words.':'कोई विकल्प चुनें या अपना सवाल लिखें।','Upload a report':'रिपोर्ट अपलोड करें','Explain medical words':'मेडिकल शब्द समझें','Prepare for a doctor visit':'डॉक्टर से मिलने की तैयारी','Find my timeline':'मेरी टाइमलाइन देखें','Type your question…':'अपना सवाल लिखें…','Send ↑':'भेजें ↑','Aa Make text easier to read':'Aa पाठ पढ़ना आसान करें','Aa Standard text size':'Aa सामान्य टेक्स्ट आकार','Help & safety':'मदद और सुरक्षा','Explore':'जानें','Overview':'डैशबोर्ड','Medical records':'मेडिकल रिकॉर्ड','Health timeline':'स्वास्थ्य टाइमलाइन','Medicine list':'दवाओं की सूची','AI health assistant':'AI स्वास्थ्य सहायक','Wellness check-in':'स्वास्थ्य चेक-इन','Visit preparation':'डॉक्टर से मिलने की तैयारी','Privacy & settings':'गोपनीयता और सेटिंग्स','Symptom notes':'लक्षण नोट्स','Health information, made clearer.':'स्वास्थ्य जानकारी, अब और आसान।','For information only · Not a medical diagnosis · Use demo data only':'केवल जानकारी के लिए · चिकित्सा निदान नहीं · केवल डेमो डेटा इस्तेमाल करें','Change website language':'वेबसाइट की भाषा बदलें'
  };
  let uiLanguage=(()=>{try{return localStorage.getItem(languageKey)||'English'}catch(_){return 'English'}})();
  function applyLanguage(){
    const map=uiLanguage==='Hindi'?hiMap:null;
    document.documentElement.lang=uiLanguage==='Hindi'?'hi':'en';
    const button=$('#languageToggle');if(button){button.textContent=uiLanguage==='Hindi'?'EN English':'हि हिन्दी';button.setAttribute('aria-label',uiLanguage==='Hindi'?'Switch website to English':'वेबसाइट हिन्दी में बदलें');button.title=uiLanguage==='Hindi'?'Switch to English':'हिन्दी में बदलें'}
    // Translate visible interface text without replacing child markup or event-bound elements.
    const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
    const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
    nodes.forEach(node=>{if(!node.dataset) return;if(!node.parentElement||node.parentElement.closest('script,style,textarea,input,option'))return;
      if(!node.__medicoreEnglish)node.__medicoreEnglish=node.nodeValue;
      const original=node.__medicoreEnglish.trim();if(!original)return;
      if(map){const translated=map[original];if(translated)node.nodeValue=node.nodeValue.replace(original,translated)}else node.nodeValue=node.__medicoreEnglish;
    });
    const placeholders={'Type your question…':'अपना सवाल लिखें…','Ask a general health-information question…':'स्वास्थ्य से जुड़ा सामान्य सवाल पूछें…','Search documents…':'दस्तावेज़ खोजें…','Search timeline…':'टाइमलाइन खोजें…'};
    if(map)Object.entries(placeholders).forEach(([en,hi])=>$$(`[placeholder="${en}"]`).forEach(el=>el.placeholder=hi));else Object.keys(placeholders).forEach(en=>$$('[placeholder]').forEach(el=>{if(Object.values(placeholders).includes(el.placeholder))el.placeholder=en}));
  }
  function bindEvents(){document.addEventListener('click',async event=>{if(event.target.closest('#languageToggle')){uiLanguage=uiLanguage==='English'?'Hindi':'English';try{localStorage.setItem(languageKey,uiLanguage)}catch(_){}renderPage();applyLanguage();toast(uiLanguage==='Hindi'?'भाषा हिन्दी में बदली गई।':'Language changed to English.');return}if(event.target.closest('#helpLauncher')){setHelpOpen($('#helpPanel').hidden);return}if(event.target.closest('#helpClose')){setHelpOpen(false);return}const helpPrompt=event.target.closest('[data-help-prompt]');if(helpPrompt){submitHelpQuestion(helpPrompt.dataset.helpPrompt);return}if(event.target.closest('#easyReadToggle')){const on=document.body.classList.toggle('easy-read-mode');$('#easyReadToggle').setAttribute('aria-pressed',String(on));$('#easyReadToggle').textContent=on?'Aa Standard text size':'Aa Make text easier to read';return}const route=event.target.closest('[data-route]');if(route){event.preventDefault();navigate(route.dataset.route);return}const recordFilter=event.target.closest('[data-record-filter]');if(recordFilter){activeRecordFilter=recordFilter.dataset.recordFilter;renderPage();return}const timelineFilter=event.target.closest('[data-timeline-filter]');if(timelineFilter){activeTimelineFilter=timelineFilter.dataset.timelineFilter;renderPage();return}const medicineFilter=event.target.closest('[data-medicine-filter]');if(medicineFilter){activeMedicineFilter=medicineFilter.dataset.medicineFilter;renderPage();return}const chip=event.target.closest('[data-symptom]');if(chip){const s=chip.dataset.symptom;state.symptoms=state.symptoms.includes(s)?state.symptoms.filter(x=>x!==s):[...state.symptoms,s];chip.classList.toggle('selected',state.symptoms.includes(s));return}const prompt=event.target.closest('[data-prompt]');if(prompt){$('#assistantQuestion').value=prompt.dataset.prompt;$('#assistantQuestion').focus();return}const action=event.target.closest('[data-action]');if(!action)return;const id=action.dataset.id;
      switch(action.dataset.action){case 'export-demo':exportData();break;case 'add-medicine':addMedicineModal();break;case 'edit-medicine':{const med=state.medicines.find(m=>String(m.id)===String(id));if(med)addMedicineModal(med);break}case 'remove-medicine':{const ok=await confirmModal('Remove medication record','Remove this user-entered record from the local demo? This does not change any real prescription.','Remove',true);if(ok){state.medicines=state.medicines.filter(m=>String(m.id)!==String(id));saveState();renderPage();toast('Medication record removed.')}break}case 'medicine-status':{const med=state.medicines.find(m=>String(m.id)===String(id));if(med){med.status=action.dataset.status;saveState();renderPage();toast('Demo status updated.')}break}case 'remove-file':{const ok=await confirmModal('Remove document','Remove this document entry from the demo library? The original file on your device will not be deleted.','Remove',true);if(ok){state.files=state.files.filter(f=>String(f.id)!==String(id));state.events=state.events.filter(e=>String(e.id)!==`upload-${id}`);saveState();renderPage();toast('Document entry removed.')}break}case 'add-event':showModal('Add timeline event',`<form id="eventForm"><div class="field"><label for="eventTitle">Event title *</label><input id="eventTitle" required maxlength="120"></div><div class="field-grid"><div class="field"><label for="eventDate">Date</label><input id="eventDate" type="date" value="${todayISO()}"></div><div class="field"><label for="eventType">Type</label><select id="eventType"><option>Consultation</option><option>Lab report</option><option>Prescription</option><option>Discharge summary</option><option>Other</option></select></div></div><div class="field"><label for="eventDesc">Notes</label><textarea id="eventDesc" maxlength="500"></textarea></div><div class="modal-actions"><button type="button" class="btn btn-secondary" data-modal-cancel>Cancel</button><button class="btn btn-primary" type="submit">Add event</button></div></form>`,()=>{const title=$('#eventTitle').value.trim();if(!title){toast('Event title is required.','error');return false}state.events.push({id:Date.now(),date:$('#eventDate').value||todayISO(),type:$('#eventType').value,title,description:$('#eventDesc').value.trim(),status:'User reported'});saveState();closeModal();renderPage();toast('Timeline event added.');return true});break;case 'save-profile':saveProfile();break;case 'save-profile-notes':state.conditions=$('#profileConditions').value;state.allergies=$('#profileAllergies').value;saveState();toast('Health notes saved.');break;case 'save-settings':$$('[data-setting]').forEach(input=>state.settings[input.dataset.setting]=input.checked);state.settings.language=$('#settingsLanguage').value;saveState();toast('Preferences saved in this browser.');break;case 'ask-assistant':askAssistant();break;case 'review-symptoms':makeSymptomSummary();break;case 'send-symptoms-to-brief':state.notes=[state.notes,`Symptom notes: ${symptomResult?.symptoms.join(', ')||''}; self-rated severity ${symptomResult?.severity||''}/10; duration ${symptomResult?.duration||''}. ${symptomResult?.notes||''}`].filter(Boolean).join('\n');saveState();navigate('consultation');toast('Symptom notes copied to the visit brief.');break;case 'print-brief':window.print();break;case 'download-brief':{const text=`CLINICAL CONVERSATION BRIEF\nPatient: ${$('#briefPatient')?.value||state.name}\nAppointment date: ${$('#briefDate')?.value||''}\n\nMAIN CONCERNS\n${$('#briefConcerns')?.value||'(Not provided)'}\n\nRECENT RECORDS\n${state.files.map(f=>`${f.name} — ${prettyDate(f.date)} (verify original)`).join('\n')||'(No documents added)'}\n\nMEDICATIONS TO VERIFY\n${state.medicines.map(m=>`${m.name} ${m.strength} — ${m.instructions}`).join('\n')||'(No medication records)'}\n\nQUESTIONS\n${$('#briefQuestions')?.value||'(Not provided)'}\n\nThis is a patient-preparation aid, not a diagnosis or official medical record.`;downloadBlob('medicore-consultation-brief.txt',text);toast('Consultation brief downloaded.');break}case 'reset-demo':{const ok=await confirmModal('Reset local demo data','This permanently clears this app’s locally stored demo profile, files metadata, timeline, medicines, and preferences from this browser.','Reset data',true);if(ok){localStorage.removeItem(storageKey);state=structuredClone(initialState);activeRecordFilter='All';activeTimelineFilter='All';activeMedicineFilter='All';renderPage();toast('Demo workspace reset.')}break}}
    });
    document.addEventListener('submit',event=>{if(event.target.id==='helpForm'){event.preventDefault();submitHelpQuestion($('#helpInput').value);return}event.preventDefault();if(event.target.id==='medicineForm'){modalResolve?.();return}if(event.target.id==='profileForm'){saveProfile();return}if(event.target.id==='checkupForm'){const form=new FormData(event.target);const entry={id:Date.now(),date:todayISO(),mood:form.get('mood'),sleep:form.get('sleep'),energy:Number($('#energy').value),activity:$('#activity').value,notes:$('#checkupNotes').value.trim()};state.checkups.push(entry);saveState();$('#checkupResult').innerHTML=`<div class="ai-callout"><span class="ai-star">✓</span><div><strong>Reflection saved</strong><p>Your check-in is saved in this browser. Consider discussing persistent concerns with your healthcare professional.</p></div></div>`;$('#checkupHistory').innerHTML=renderCheckupHistory();toast('Weekly reflection saved.');return}if(event.target.id==='eventForm'){modalResolve?.();return}});
    document.addEventListener('input',event=>{if(event.target.id==='recordSearch'){const q=event.target.value.toLowerCase();const filtered=state.files.filter(f=>(activeRecordFilter==='All'||f.kind===activeRecordFilter)&&`${f.name} ${f.kind} ${f.summary}`.toLowerCase().includes(q));$('#recordList').innerHTML=renderFileList(filtered)}if(event.target.id==='timelineSearch'){const q=event.target.value.toLowerCase();$$('[data-search-text]').forEach(el=>el.hidden=!el.dataset.searchText.includes(q))}if(event.target.id==='severity'){state.severity=Number(event.target.value);$('#severityValue').textContent=`${event.target.value} / 10`}if(event.target.id==='energy')$('#energyValue').textContent=`${event.target.value} / 10`;if(event.target.id==='symptomSearch'){const q=event.target.value.toLowerCase();$$('[data-symptom]').forEach(el=>el.hidden=!el.dataset.symptom.toLowerCase().includes(q))}});
    $('#menuToggle').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#sidebarBackdrop').classList.toggle('show')});$('#sidebarBackdrop').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#sidebarBackdrop').classList.remove('show')});$('#themeToggle').addEventListener('click',()=>{document.body.classList.toggle('dark-mode');state.settings.theme=document.body.classList.contains('dark-mode')?'dark':'light';updateThemeControl();saveState()});$('#userButton').addEventListener('click',()=>navigate('profile'));$('#modalClose').addEventListener('click',closeModal);$('#modal').addEventListener('click',event=>{if(event.target===$('#modal'))closeModal()});$('#modalBody').addEventListener('click',event=>{if(event.target.closest('[data-modal-cancel]')){closeModal();return}if(event.target.closest('[data-modal-confirm]')){const result=modalResolve?.();if(result!==false)closeModal()}});$('#modalBody').addEventListener('submit',event=>{event.preventDefault();const result=modalResolve?.();if(result!==false&&$('#modal').open)closeModal()});
    $('#pageContent').addEventListener('click',event=>{if(event.target.closest('#chooseFiles'))$('#fileInput').click()});$('#pageContent').addEventListener('change',event=>{if(event.target.id==='fileInput'){handleFiles([...event.target.files]);event.target.value=''}if(event.target.matches('[data-setting]')){state.settings[event.target.dataset.setting]=event.target.checked;saveState()}});$('#pageContent').addEventListener('dragover',event=>{const zone=event.target.closest('#uploadZone');if(zone){event.preventDefault();zone.classList.add('dragover')}});$('#pageContent').addEventListener('dragleave',event=>{const zone=event.target.closest('#uploadZone');if(zone)zone.classList.remove('dragover')});$('#pageContent').addEventListener('drop',event=>{const zone=event.target.closest('#uploadZone');if(zone){event.preventDefault();zone.classList.remove('dragover');handleFiles([...event.dataTransfer.files])}});
    document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#helpPanel').hidden)setHelpOpen(false)});
    window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(routeNames[route]&&route!==currentRoute){currentRoute=route;renderPage()}});
  }
  function updateThemeControl(){const dark=document.body.classList.contains('dark-mode');const button=$('#themeToggle');if(button){button.textContent=dark?'☼':'◐';button.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');button.title=dark?'Switch to light mode':'Switch to dark mode'}const meta=$('#themeColorMeta');if(meta)meta.setAttribute('content',dark?'#0F1E3A':'#FFFFFF')}
  function initSpotlight(){
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    let frame = 0;
    document.addEventListener('pointermove', event => {
      if (frame) cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        document.documentElement.style.setProperty('--spot-x', `${event.clientX}px`);
        document.documentElement.style.setProperty('--spot-y', `${event.clientY}px`);
        frame = 0;
      });
    }, { passive: true });
  }
  function init(){if(state.settings.theme==='dark')document.body.classList.add('dark-mode');const nameNode=$('#sidebarName');if(nameNode)nameNode.textContent=state.name;const avatar=$('.profile-mini .avatar');if(avatar)avatar.textContent=String(state.name||'MC').split(/\\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();updateThemeControl();const route=location.hash.slice(1);if(routeNames[route])currentRoute=route;bindEvents();renderPage();initSpotlight()}
  init();
})();
